    function testFuzz_property(address newOwner) public {
        // admissible domain: newOwner can be any address (including zero) — keep wide
        // ensure caller is the current owner
        // deployer of c in setUp() is this test contract, so this contract is owner

        // Call transferOwnership as the owner to set newOwner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: if the call succeeded, the contract's owner getter must equal the supplied newOwner.
        // If the call reverted, we accept that behavior (but in this contract transferOwnership should not revert when called by owner).
