contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary address that the fuzzer will try as the caller.
    // General rule: only the owner (initially address(this) that deployed c) can successfully execute owned();
