        // We now perform two attempts to change owner to newOwner:
        // 1) Direct call from ownerEoa (msg.sender == owner) will succeed on the reference only if ownerEoa currently equals c.owner.
        // 2) Call routed through intermediary contract: intermediary calls c.transferOwnership(newOwner) while the tx.origin is ownerEoa.
        // The distinguishing situation: when msg.sender != c.owner but tx.origin == c.owner, mutant allows change while reference disallows.

        // To create the distinguishing input without changing C's storage directly, we choose ownerEoa == address(this) so that
        // we can act as the owner (msg.sender == c.owner) when needed. We constrained ownerEoa accordingly above.
        // For the case where msg.sender != owner, we will have the intermediary contract call c.transferOwnership while we (ownerEoa)
        // are the tx.origin by doing vm.prank(ownerEoa) and then having ownerEoa call intermediary.doCall(address(c), newOwner).

        // First, ensure c.owner equals address(this) by making a direct call from address(this) if possible.
        // At deploy, owner is address(0). Only an existing owner can call transferOwnership; since owner==0, no one can set it.
        // To keep the test valid for the reference implementation for all admissible inputs, we instead assert a property that does not require
        // initializing owner: the rule we assert is that if the direct msg.sender equals c.owner then a direct call succeeds, and an indirect
        // call where msg.sender != c.owner but tx.origin == c.owner does not succeed. We construct that by first checking current owner value.

        address initialOwner = c.owner();

        // We will only proceed with the distinguishing scenario when initialOwner is non-zero and equal to ownerEoa (which we limited to address(this) or zero).
        // Restrict to the case initialOwner == address(this) to make the scenario meaningful.
        vm.assume(initialOwner == address(this));

        // 1) Direct call from the owner (msg.sender == c.owner) should succeed on the reference: try/catch to capture success
        bool okDirect;
        try c.transferOwnership{ }(newOwner) {
            okDirect = true;
        } catch {
            okDirect = false;
        }

        // Reset owner back to initialOwner if it changed to keep experiment consistent: if direct call succeeded, owner is newOwner now.
        if (okDirect) {
            // restore owner to initialOwner by calling transferOwnership back from newOwner (we can only do that if newOwner is this contract)
            // To avoid additional complexity, require that newOwner == address(this) or revert the scenario; keep wide by assuming newOwner can be anything,
            // but if okDirect and newOwner != address(this) we cannot restore; thus avoid this path by assuming newOwner == address(this) when okDirect.
            vm.assume(newOwner == address(this));
            // call back to restore
            try c.transferOwnership{ }(initialOwner) {
            } catch {
            }
        }

        // 2) Indirect call: make tx.origin == initialOwner while intermediary is msg.sender.
        // ownerEoa == initialOwner == address(this) by assumptions, so we simulate tx where an EOA (address(this)) calls intermediary which then calls c.
        // To make tx.origin equal address(this), we have to have an external call originate from address(this) to intermediary.
        // Use vm.prank to set msg.sender for the external call to intermediary to address(this), which will then call c where intermediary is msg.sender and tx.origin==address(this).

        // perform the routed call: from ownerEoa (address(this)) call intermediary.doCall to invoke c.transferOwnership
        bool okIndirect;
        vm.prank(address(this));
        try intermediary.doCall(address(c), newOwner) {
            okIndirect = true;
        } catch {
            okIndirect = false;
        }

        // The universal property we assert: if the indirect call has msg.sender != c.owner but tx.origin == c.owner, then the reference must NOT allow the indirect call to change owner.
        // We observe this by checking that okIndirect implies okDirect (i.e., indirect success cannot occur while direct owner-call would fail). For the reference, any successful ownership change
        // must be performed by the direct owner (so an indirect success without direct success is impossible). The mutant allows indirect success while direct fails.

        // Formulate single assertion reading c through its public getter: ensure that whenever the indirect call succeeded, the direct call must have succeeded as well.
        // This captures that ownership changes cannot occur from intermediary while direct-owner-call would be disallowed.
        assertTrue(!okIndirect || okDirect);
    }
}

// Minimal intermediary that simply calls transferOwnership on target
contract Caller {
    function doCall(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}
